// Command gen-build-config writes the packaged app's configuration into a Go
// source file from environment variables. CI supplies the values from GitHub
// secrets/variables; the generated file is git-ignored and never committed.
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

var fields = []struct {
	env   string
	field string
}{
	{"GOOGLE_OAUTH_CLIENT_ID", "BuildGoogleOAuthClientID"},
	{"GOOGLE_OAUTH_CLIENT_SECRET", "BuildGoogleOAuthClientSecret"},
	{"ARGUS_GOOGLE_CLIENT_ID", "BuildArgusGoogleClientID"},
	{"ARGUS_GOOGLE_CLIENT_SECRET", "BuildArgusGoogleClientSecret"},
	{"ARGUS_GITHUB_CLIENT_ID", "BuildGithubClientID"},
	{"ARGUS_GITHUB_CLIENT_SECRET", "BuildGithubClientSecret"},
	{"ARGUS_PUBLIC_URL", "BuildPublicURL"},
}

func main() {
	root, err := findRoot()
	if err != nil {
		fail(err)
	}
	var b strings.Builder
	b.WriteString("// Code generated by tools/gen-build-config; DO NOT EDIT.\n\npackage Shared\n\nfunc init() {\n")
	for _, f := range fields {
		if v := os.Getenv(f.env); v != "" {
			fmt.Fprintf(&b, "\t%s = %s\n", f.field, strconv.Quote(v))
		}
	}
	b.WriteString("}\n")
	path := filepath.Join(root, "Services", "Shared", "build_config_generated.go")
	if err := os.WriteFile(path, []byte(b.String()), 0o600); err != nil {
		fail(err)
	}
	fmt.Printf("generated build config from %d environment values\n", countSet())
}

func countSet() int {
	n := 0
	for _, f := range fields {
		if os.Getenv(f.env) != "" {
			n++
		}
	}
	return n
}

func findRoot() (string, error) {
	dir, err := os.Getwd()
	if err != nil {
		return "", err
	}
	for {
		if info, err := os.Stat(filepath.Join(dir, "skills")); err == nil && info.IsDir() {
			return dir, nil
		}
		parent := filepath.Dir(dir)
		if parent == dir {
			return "", fmt.Errorf("cannot find repository root from %s", dir)
		}
		dir = parent
	}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, "gen-build-config:", err)
	os.Exit(1)
}
